function marketIndexBoard(compact=false){const data=state.marketIndices,quotes=data?.quotes||[],visible=compact?quotes.slice(0,4):quotes;return `<section class="suvi-quote-board"><div class="suvi-quote-board-head"><div><small>市场看板</small><h2>大盘行情</h2></div><div class="suvi-quote-head-actions"><span>${quotes.length?`${esc(quotes[0].status)} · ${esc(dt(quotes[0].asOf))}`:state.marketIndicesLoading?'正在更新':'行情未更新'}</span>${compact?'<button type="button" data-market-tab="indexes">查看全部指数 →</button>':'<button type="button" data-market-action="refresh-indexes">刷新行情 ↻</button>'}</div></div>${state.marketIndicesError?`<div class="suvi-board-alert">${esc(state.marketIndicesError)} <button type="button" data-market-action="refresh-indexes">重试</button></div>`:''}${visible.length?`<div class="suvi-quote-grid">${visible.map(q=>`<article class="suvi-quote-tile"><span>${esc(q.name)}</span><strong>${num(q.point)}</strong><b class="${tone(q.changePct)}">${pct(q.changePct)}</b><small>${esc(q.status)}</small></article>`).join('')}</div>`:`<div class="suvi-board-empty">${state.marketIndicesLoading?'正在读取指数行情…':'暂时没有可用的指数行情。'}</div>`}<p class="suvi-board-source">来源：${esc(data?.source||'腾讯行情')} · 行情时间按北京时间展示。指数涨跌不代表基金净值或账户收益。</p></section>`}
