function resultView(result,allowPlan=true,parameterMarkup=''){if(!result)return `${parameterMarkup}<div class="panda-result-empty"><div><span class="result-mark">◌</span><strong>正在准备默认回测</strong><p>页面会按策略默认参数读取真实数据；缺少数据时将显示具体原因。</p></div></div>`;if(result.status!=='ok')return `${parameterMarkup}<div class="panda-result-blocked"><b>!</b><div><strong>暂无法判断</strong><p>${esc((result.missingData||[]).join('；')||'数据接口未返回完整结果。')}</p><small>来源：${esc(result.source||'策略数据契约')}</small></div></div>`;const m=result.metrics||{},flow=result.cashFlow||{},absolute=m.absoluteReturnPct??m.returnPct,audit=result.audit||{},auditText=audit.passed?'计算校验通过':'旧结果未完成新口径校验';return `<div class="panda-metrics"><div><small>策略累计收益率</small><strong class="${tone(absolute)}">${pct(absolute)}</strong></div><div><small>超额收益</small><strong class="${tone(m.excessReturnPct)}">${pct(m.excessReturnPct)}</strong></div><div><small>${esc(result.benchmarkName||'基准')}收益</small><strong class="${tone(m.benchmarkReturnPct)}">${pct(m.benchmarkReturnPct)}</strong></div><div><small>资金收益率</small><strong class="${tone(m.capitalReturnPct)}">${pct(m.capitalReturnPct)}</strong></div><div><small>最大回撤</small><strong class="${tone(m.maxDrawdownPct)}">${num(m.maxDrawdownPct)}%</strong></div><div><small>累计投入</small><strong>${money(flow.totalInvested)}</strong></div><div><small>累计收益</small><strong class="${tone(flow.netProfit)}">${signed(flow.netProfit)}</strong></div><div><small>期末金额</small><strong>${money(flow.endingValue)}</strong></div></div>${parameterMarkup}<div class="panda-chart-wrap">${chart(result)}<div class="panda-chart-legend"><span><i class="strategy"></i>策略累计收益率</span><span><i class="dash"></i>${esc(result.benchmarkName||'比较基准')}</span><span><i class="buy"></i>买入</span><span><i class="sell"></i>卖出</span></div></div><div class="panda-result-note"><b>${esc(auditText)}</b> · ${esc(audit.formula||'超额收益 = 策略同期累计收益率 - 同期基准收益率')}。区间：${esc(result.period?.start||'—')} 至 ${esc(result.period?.end||result.dataAsOf||'—')}。来源：${esc(result.source||'旧记录未保存来源')}。手续费：${flow.fees===null?'未计入，接口未返回完整历史费率':money(flow.fees)}。${flow.feeNote?esc(flow.feeNote)+' ':''}${esc(result.riskStatement||'历史回测不代表未来收益。')} 本结果是规则模拟，不是账户实际收益。</div><div class="panda-result-tabs"><strong>交易依据</strong><span>${result.trades?.length??'旧记录未保存明细'} 条</span></div>${tradesTable(result)}${allowPlan?`<div class="panda-save-row"><div><strong>保存为个人计划</strong><small>保存当前版本、标的、参数和回测引用；保存后仍需手动开启跟踪。</small></div>${button('保存计划','save-plan','','primary')}</div>`:''}`}
function detailBacktest(result){if(!result)return '<div class="panda-result-empty"><div><span class="result-mark">◌</span><strong>正在准备默认回测</strong><p>读取真实数据后在这里同步展示收益与曲线。</p></div></div>';if(result.status!=='ok')return `<div class="panda-result-blocked"><b>!</b><div><strong>暂无法判断</strong><p>${esc((result.missingData||[]).join('；')||'数据接口未返回完整结果。')}</p><small>来源：${esc(result.source||'策略数据契约')}</small></div></div>`;const m=result.metrics||{},flow=result.cashFlow||{},absolute=m.absoluteReturnPct??m.returnPct,audit=result.audit||{},auditText=audit.passed?'计算校验通过':'旧结果未完成新口径校验';return `<div class="panda-metrics"><div><small>策略累计收益率</small><strong class="${tone(absolute)}">${pct(absolute)}</strong></div><div><small>超额收益</small><strong class="${tone(m.excessReturnPct)}">${pct(m.excessReturnPct)}</strong></div><div><small>${esc(result.benchmarkName||'基准')}收益</small><strong class="${tone(m.benchmarkReturnPct)}">${pct(m.benchmarkReturnPct)}</strong></div><div><small>资金收益率</small><strong class="${tone(m.capitalReturnPct)}">${pct(m.capitalReturnPct)}</strong></div><div><small>最大回撤</small><strong class="${tone(m.maxDrawdownPct)}">${num(m.maxDrawdownPct)}%</strong></div><div><small>累计投入</small><strong>${money(flow.totalInvested)}</strong></div><div><small>累计收益</small><strong class="${tone(flow.netProfit)}">${signed(flow.netProfit)}</strong></div><div><small>期末金额</small><strong>${money(flow.endingValue)}</strong></div></div><div class="panda-chart-wrap">${chart(result)}<div class="panda-chart-legend"><span><i class="strategy"></i>策略累计收益率</span><span><i class="dash"></i>${esc(result.benchmarkName||'比较基准')}</span><span><i class="buy"></i>买入</span><span><i class="sell"></i>卖出</span></div></div><div class="panda-result-note"><b>${esc(auditText)}</b> · ${esc(audit.formula||'超额收益 = 策略同期累计收益率 - 同期基准收益率')}。区间：${esc(result.period?.start||'—')} 至 ${esc(result.period?.end||result.dataAsOf||'—')}。来源：${esc(result.source||'旧记录未保存来源')}。手续费：${flow.fees===null?'未计入，接口未返回完整历史费率':money(flow.fees)}。${flow.feeNote?esc(flow.feeNote)+' ':''}${esc(result.riskStatement||'历史回测不代表未来收益。')} 本结果是规则模拟，不是账户实际收益。</div>`}
function detailControls(result,parameterMarkup){const evidence=result?.status==='ok'?`<div class="panda-result-tabs"><strong>交易依据</strong><span>${result.trades?.length??'旧记录未保存明细'} 条</span></div><div class="panda-detail-evidence">${tradesTable(result)}</div><div class="panda-save-row"><div><strong>保存为个人计划</strong><small>保存当前版本、标的、参数和回测引用；保存后仍需手动开启跟踪。</small></div>${button('保存计划','save-plan','','primary')}</div>`:'<div class="panda-history-note">回测完成后，这里会列出每一次买卖及其触发依据。</div>';return `${parameterMarkup}${evidence}`}
function detail(item){const variant=currentVariant(item.id),params=state.result?.strategyId===item.id&&state.result.parameters?state.result.parameters:(variant?.params||item.defaultParams||{}),versions=state.variants.filter(x=>x.strategyId===item.id).sort((a,b)=>String(b.updatedAt).localeCompare(String(a.updatedAt))),example=showcaseBest(item),code=state.result?.fundCode||variant?.fundCode||state.pendingCode||example?.fundCode||item.defaultFundCode||'',isDefault=(item.params||[]).every(spec=>String(params?.[spec.key]??'')===String(item.defaultParams?.[spec.key]??spec.default??'')),versionList=versions.map(v=>`<button class="panda-version-row" data-action="load-variant" data-id="${esc(v.id)}"><strong>${esc(v.name)} · 配置 v${v.version}</strong><small>${esc(v.fundCode||'固定基金池')} · ${esc(dt(v.updatedAt))} · 基于 Skill v${esc(v.baseVersion)}</small></button>`).join(''),versionPanel=versions.length?`<details class="panda-version-panel"><summary>个人配置版本 · ${versions.length}</summary><div class="panda-version-list">${versionList}</div></details>`:'',parameterMarkup=parameterModule(item,params,code,example,variant),resultTitle=state.defaultLoading===item.id?'正在计算默认回测':isDefault?'默认回测':'当前参数回测',resultMeta=state.result?.status==='ok'?`数据截至 ${esc(state.result.dataAsOf)} · ${esc(state.result.source)}`:'策略目录配置样本 · 默认参数';return `<div class="panda-detail-shell"><section class="panda-detail-left panda-detail-intro"><div class="panda-detail-titlebar"><button class="panda-back" data-action="back-library">← 返回策略</button><span class="strategy-badge">${esc(item.category)}</span></div><div class="panda-strategy-title"><h1>${esc(variant?.name||item.name)}</h1><p>${esc(item.description)}</p><div class="strategy-detail-next-actions"><button type="button" data-action="edit-params">调整参数回测</button><button type="button" data-action="save-plan">制定计划</button></div><div class="panda-explain-grid"><div><small>它怎么做</small><ul>${(item.rules||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div><div><small>适合谁</small><p>${esc(item.suitableFor)}</p></div><div><small>需要接受</small><p>${esc(item.tradeoff)}</p></div><div><small>数据口径</small><p>${esc(item.dataBasis)} · ${state.result?.period?`${esc(state.result.period.start)} 至 ${esc(state.result.period.end)}`:'进入后自动验证默认案例'}</p></div></div></div>${versionPanel}</section>${jobPanel()}<form id="panda-strategy-form" class="panda-parameter-section panda-detail-form"><div class="panda-detail-flow"><div><b>同一回测版本</b><span>右侧当前参数生成左侧收益、曲线和下方交易依据；重新回测后两侧同步更新。</span></div><em>参数配置&nbsp; → &nbsp;回测结果&nbsp; → &nbsp;交易依据</em></div><div class="panda-detail-workspace"><section class="panda-backtest-column"><div class="panda-column-head"><span>01</span><div><h3>${resultTitle}</h3><small>${resultMeta}</small></div></div>${detailBacktest(state.result)}</section><section class="panda-controls-column"><div class="panda-column-head"><span>02</span><div><h3>参数与交易依据</h3><small>查看本次配置；需要时修改参数并重新计算。</small></div></div>${detailControls(state.result,parameterMarkup)}</section></div></form></div>`}

function holdingsPage(){const innerNav=`<nav class="suvi-module-nav" aria-label="看持仓内部导航"><button type="button" data-nav="holdings" data-anchor="holding-detail-section">持仓明细</button><button type="button" data-nav="holdings" data-anchor="holding-analysis-section">持仓分析</button></nav>`;if(state.holdingsError)return `${heading('MY · ACCOUNT','我的持仓','读取同花顺爱基金当前真实持仓。')}${innerNav}<div class="panda-result-blocked"><b>!</b><div><strong>账户数据暂不可用</strong><p>${esc(state.holdingsError)}</p>${button('前往账户连接','nav','data-nav="account"','primary')}</div></div>`;if(!state.holdings)return `${heading('MY · ACCOUNT','我的持仓','正在读取真实账户数据。')}${innerNav}<div class="panda-loading"><i></i>正在查询同花顺爱基金…</div>`;const s=state.holdings.summary||{},funds=state.holdings.funds||[];return `${heading('MY · ACCOUNT','我的持仓','持仓、钱包与收益来自同花顺爱基金；组合历史分析使用扶摇复权净值。',button('刷新账户','refresh-holdings','','quiet'))}${innerNav}<div class="panda-plan-summary"><div><small>基金资产</small><strong>${money(s.totalAmount)}</strong></div><div><small>持有收益</small><strong class="${tone(s.holdIncome)}">${signed(s.holdIncome)}</strong></div><div><small>持仓数量</small><strong>${funds.length}</strong></div><div><small>数据来源</small><strong>同花顺</strong></div></div><div class="panda-holdings-layout"><section><div class="panda-section-head"><div><h2>持仓明细</h2><p>点击一只基金查看真实复权净值和策略入口。</p></div></div><div class="panda-holding-list">${funds.map(f=>`<button data-action="drill-fund" data-code="${esc(f.fundCode)}"><span><strong>${esc(f.fundName||f.fundCode)}</strong><small>${esc(f.fundCode)} · ${f.holdVol==='待确认'?'份额待确认':'已确认持仓'}</small></span><span><strong>${money(f.totalAmount)}</strong><small class="${tone(f.holdIncome)}">持有收益 ${signed(f.holdIncome)}</small></span></button>`).join('')||'<div class="panda-plan-empty">账户当前没有基金持仓。</div>'}</div></section><section>${portfolioPanel()}</section></div>`}
function alignComparison(primary,comparison){const bench=(comparison||[]).slice().sort((a,b)=>String(a.date).localeCompare(String(b.date)));let cursor=-1,current=null;return (primary||[]).map(row=>{while(cursor+1<bench.length&&String(bench[cursor+1].date)<=String(row.date)){cursor++;current=bench[cursor]}return {date:row.date,value:row.value,benchmark:current?.value??null}})}
function portfolioPanel(){if(state.analysisError)return `<div class="panda-result-blocked"><b>!</b><div><strong>组合分析暂不可用</strong><p>${esc(state.analysisError)}</p></div></div>`;if(!state.analysis)return '<div class="panda-loading"><i></i>正在计算持仓归因与风险…</div>';const a=state.analysis,m=a.metrics||{},aligned=alignComparison(a.history,a.benchmark);return `<div class="panda-section-head"><div><h2>持仓归因</h2><p>截至 ${esc(a.asOf)} · 当前权重历史模拟</p></div></div><div class="panda-metrics compact"><div><small>模拟收益</small><strong class="${tone(m.returnPct)}">${pct(m.returnPct)}</strong></div><div><small>最大回撤</small><strong class="${tone(m.maxDrawdownPct)}">${num(m.maxDrawdownPct)}%</strong></div><div><small>年化波动</small><strong>${num(m.volatilityPct)}%</strong></div><div><small>夏普</small><strong class="${tone(m.sharpe)}">${num(m.sharpe)}</strong></div></div><div class="panda-chart-wrap">${lineChart(aligned,Boolean(a.benchmark?.length))}<div class="panda-chart-legend"><span><i class="strategy"></i>组合模拟</span><span><i class="dash"></i>比较基准</span></div></div><div class="panda-allocation">${(a.allocations||[]).map(x=>`<div><span><i style="background:${esc(x.color)}"></i>${esc(x.name)} · ${x.funds} 只</span><strong>${num(x.percent)}%</strong></div>`).join('')}</div><div class="panda-result-note">${esc(a.method)}<br>来源：${esc(a.source)}</div>`}
function allocationPage(){
  const funds=state.holdings?.funds||[],total=n(state.holdings?.summary?.totalAmount);
  if(state.holdingsError)return `${heading('PORTFOLIO','配资产','根据你账户中的实际基金持仓查看配置情况。')}<div class="panda-result-blocked"><b>!</b><div><strong>账户数据暂不可用</strong><p>${esc(state.holdingsError)}</p>${button('前往账户连接','nav','data-nav="account"','primary')}</div></div>`;
  if(!state.holdings)return `${heading('PORTFOLIO','配资产','根据你账户中的实际基金持仓查看配置情况。')}<div class="panda-loading"><i></i>正在读取同花顺爱基金账户…</div>`;
  if(!funds.length)return `${heading('PORTFOLIO','配资产','根据你账户中的实际基金持仓查看配置情况。')}<div class="panda-plan-empty">当前账户没有基金持仓。连接账户并产生持仓后，这里会展示实际基金构成。</div>`;
  const rows=funds.slice().sort((a,b)=>(n(b.totalAmount)||0)-(n(a.totalAmount)||0));
  return `${heading('PORTFOLIO','配资产','查看实际持仓构成与历史模拟分析；这里不代表个性化投资建议。',button('查看我的持仓','nav','data-nav="holdings"','quiet'))}<div class="panda-plan-summary"><div><small>基金资产</small><strong>${money(total)}</strong></div><div><small>持有收益</small><strong class="${tone(state.holdings.summary?.holdIncome)}">${signed(state.holdings.summary?.holdIncome)}</strong></div><div><small>持有基金</small><strong>${funds.length} 只</strong></div><div><small>数据来源</small><strong>同花顺账户</strong></div></div><div class="panda-holdings-layout"><section><div class="panda-section-head"><div><h2>账户基金构成</h2><p>按持仓金额占比排序 · 持仓金额来自账户接口</p></div></div><div class="panda-holding-list">${rows.map(f=>{const amount=n(f.totalAmount),share=amount!==null&&total>0?`${(amount/total*100).toFixed(1)}%`:'—';return `<div class="panda-watch-row"><span><strong>${esc(f.fundName||f.fundCode||'基金名称未提供')}</strong><small>${esc(f.fundCode||'基金代码未提供')}</small></span><span><strong>${money(f.totalAmount)}</strong><small>占基金资产 ${share}</small></span></div>`}).join('')}</div><p class="panda-result-note">账户数据更新时间：${esc(dt(state.holdings.fetchedAt))}。按金额计算的比例仅反映当前基金账户，不包括未接入的其他资产。</p></section><section>${portfolioPanel()}</section></div>`
}
function watchlistPage(embedded=false){return `${embedded?'<div class="suvi-module-section-head"><h2>我的自选</h2><p>自选是本地研究清单，不代表真实持仓。</p></div>':heading('MY · LOCAL LIST','我的自选','自选是本地研究清单，不代表真实持仓。')}<form id="watch-form" class="panda-inline-form"><input name="code" pattern="[0-9]{6}" maxlength="6" placeholder="6 位基金代码" required><input name="name" maxlength="80" placeholder="基金名称（可选）"><button class="panda-button primary">添加自选</button></form><div class="panda-holding-list">${state.watchlist.map(x=>`<div class="panda-watch-row"><button data-action="drill-fund" data-code="${esc(x.code)}"><span><strong>${esc(x.name||x.code)}</strong><small>${esc(x.code)}</small></span></button><div>${button('用于策略','pick-for-strategy',`data-code="${esc(x.code)}"`,'quiet')}${button('移除','remove-watch',`data-code="${esc(x.code)}"`,'quiet')}</div></div>`).join('')||'<div class="panda-plan-empty">还没有自选基金。</div>'}</div>`}
function planCards(){return state.plans.map(plan=>{const signal=plan.latestSignal,label={draft:'草稿',active:'跟踪中',paused:'已暂停',archived:'已归档'}[plan.status]||plan.status,run=state.runs.find(x=>x.id===plan.backtestRunId),perf=plan.performance||(run?{totalInvested:run.cashFlow?.totalInvested,netProfit:run.cashFlow?.netProfit,returnPct:run.metrics?.absoluteReturnPct??run.metrics?.returnPct,benchmarkReturnPct:run.metrics?.benchmarkReturnPct,excessReturnPct:run.metrics?.excessReturnPct,dataAsOf:run.dataAsOf}:null),rate=n(perf?.returnPct),barWidth=Math.min(100,Math.abs(rate||0)*2);return `<article class="panda-plan-card"><div class="panda-plan-main"><div class="panda-plan-title"><strong>${esc(plan.name)}</strong><span class="panda-plan-status ${esc(plan.status)}">${label}</span></div><p>${esc(plan.fundCode||'行业基金池')} · ${esc(findStrategy(plan.strategyId)?.name||plan.strategyId)} · v${esc(plan.strategyVersion)}</p>${plan.investmentGoal||plan.capitalUseHorizon?`<small>目标：${esc(plan.investmentGoal||'未填写')}${plan.capitalUseHorizon?` · 资金使用时间：${esc(plan.capitalUseHorizon)}`:''}</small>`:''}<small>回测数据截至 ${esc(plan.backtestDataAsOf||perf?.dataAsOf||'—')} · ${plan.lastCheckedAt?'最近检查 '+esc(dt(plan.lastCheckedAt)):'尚未检查'}</small></div><div class="panda-plan-signal"><strong>${esc(signal?.status==='ok'?(signal.state||'等待新信号'):'暂无法判断')}</strong><small>${esc(signal?.dataAsOf?'数据日期 '+signal.dataAsOf:'等待首次检查')}</small><em>${esc(signal?.reason||(signal?.missingData||[])[0]||'启用跟踪后检查最新状态')}</em></div><div class="panda-plan-actions">${plan.status==='draft'?button('开启跟踪','plan-action',`data-id="${plan.id}" data-plan-action="enable"`,'primary'):''}${plan.status==='active'?button('立即检查','plan-action',`data-id="${plan.id}" data-plan-action="check"`,'quiet')+button('暂停','plan-action',`data-id="${plan.id}" data-plan-action="pause"`,'quiet'):''}${plan.status==='paused'?button('恢复','plan-action',`data-id="${plan.id}" data-plan-action="enable"`,'primary'):''}${plan.status!=='archived'?button('归档','plan-action',`data-id="${plan.id}" data-plan-action="archive"`,'quiet'):''}</div><div class="panda-plan-performance"><div class="panda-plan-performance-head"><small>关联回测快照 · 不代表账户实际收益</small><span>${perf?'数据截至 '+esc(perf.dataAsOf||plan.backtestDataAsOf||'—'):'暂无可追溯结果'}</span></div><div class="panda-plan-kpis"><span>模拟累计投入 <b>${money(perf?.totalInvested)}</b></span><span>模拟累计收益 <b class="${tone(perf?.netProfit)}">${signed(perf?.netProfit)}</b></span><span>策略累计收益 <b class="${tone(rate)}">${pct(rate)}</b></span><span>同期基准收益 <b class="${tone(perf?.benchmarkReturnPct)}">${pct(perf?.benchmarkReturnPct)}</b></span><span>超额收益 <b class="${tone(perf?.excessReturnPct)}">${pct(perf?.excessReturnPct)}</b></span></div><div class="panda-plan-formula">${esc(perf?.formula||'超额收益 = 策略同期累计收益率 - 同期基准收益率')}</div><div class="panda-return-bar"><i class="${tone(rate)}" style="width:${barWidth}%"></i></div></div></article>`}).join('')||'<div class="panda-plan-empty">还没有策略计划。</div>'}
function strategyDetailWithAssistant(item){return `<div class="strategy-detail-page"><div class="strategy-primary">${detail(item)}</div>${strategyComparePanel()}<div class="strategy-idle-chat-host" id="strategy-idle-chat-host">${strategyIdleEntry(item)}</div></div>`}
function plansPage(){return `${strategyModuleNav('plans')}${heading('MY PLANS','我的计划',state.planPerformanceLoading?'正在补齐旧计划的基准和超额收益…':'保存、启用、暂停和归档策略计划；信号在应用运行期间每 30 分钟检查。')}<div class="panda-plan-list">${planCards()}</div>`}
function historyPage(){return `${strategyModuleNav('history')}${heading('RUN HISTORY','运行历史','每条记录均可打开回看指标、参数、曲线、交易位置和数据口径。')}<div class="panda-history-list">${state.runs.slice().reverse().map(run=>{const value=run.metrics?.absoluteReturnPct??run.metrics?.returnPct;return `<button class="panda-run-card" data-action="open-run" data-id="${esc(run.id)}"><div><strong>${esc(findStrategy(run.strategyId)?.name||run.strategyId)}</strong><small>${esc(run.fundCode||'行业基金池')} · Skill v${esc(run.strategyVersion)} · ${esc(dt(run.createdAt))}</small></div><div class="panda-run-result"><strong class="${tone(value)}">${run.status==='ok'?pct(value):'暂无法判断'}</strong><small>${esc(run.dataAsOf?'数据截至 '+run.dataAsOf:(run.missingData||[]).join('；'))}</small></div><span>查看回测 →</span></button>`}).join('')||'<div class="panda-plan-empty">还没有回测记录。</div>'}</div>`}
function accountPage(){const connected=Boolean(state.holdings),status=state.accountBusy?'正在等待扫码确认…':connected?`账户已连接，当前读取到 ${(state.holdings.funds||[]).length} 只基金持仓。`:state.holdingsError||'尚未取得账户数据。',disabled=state.accountBusy?'disabled':'',action=connected?button('切换账户','switch-account',disabled,state.accountBusy?'quiet':'primary'):button('扫码连接账户','login-fund',disabled,state.accountBusy?'quiet':'primary');return `${heading('ACCOUNT · READ ONLY','账户与连接','连接同花顺爱基金后，Agent 可在单个会话授权范围内只读查询持仓和订单。')}<div class="panda-connect-grid"><section><span>◎</span><h2>同花顺爱基金</h2><p>${esc(status)}</p><div class="panda-account-actions">${action}${connected?button('刷新账户','refresh-holdings',disabled,'quiet'):''}</div></section><section><span>▣</span><h2>权限边界</h2><p>切换账户会替换本机当前同花顺授权；Agent 仍只能查询、研究和管理本地计划，不会提交申购、赎回、撤单或支付。</p></section></div>`}
function modelRows(){const value=D.status?.models,rows=Array.isArray(value?.data)?value.data:Array.isArray(value?.models)?value.models:[];return rows.filter(x=>x?.id&&!x.hidden)}
function savedProviderForPreset(preset){if(!preset)return null;const rows=D.settings?.providers||[],active=rows.find(x=>x.id===D.settings?.activeProviderId&&x.baseUrl===preset.baseUrl);return active||rows.find(x=>x.baseUrl===preset.baseUrl)||null}
