  const models=modelRows(),settings=D.settings||{},selected=models.find(x=>x.id===settings.subscriptionModel)?.id||models.find(x=>x.isDefault)?.id||models[0]?.id,model=models.find(x=>x.id===selected),efforts=(model?.supportedReasoningEfforts||[]).map(x=>typeof x==='string'?x:x?.reasoningEffort).filter(Boolean),
    activeProvider=settings.providers?.find(x=>x.id===settings.activeProviderId),apiProvider=activeProvider||settings.providers?.[0]||{},apiEffort=apiProvider.effort||'high',codexActive=settings.activeMode!=='api',presetForProvider=API_PRESETS.find(x=>x.baseUrl===apiProvider.baseUrl),legacyProvider=apiProvider.id&&!presetForProvider?apiProvider:null,defaultPreset=presetForProvider?.id||(legacyProvider?`saved:${legacyProvider.id}`:'openai'),apiDefaults=presetForProvider||API_PRESETS[0],savedPresets=settings.providers||[],providerForForm=legacyProvider||savedProviderForPreset(apiDefaults);
