function render(){
  const content=$('#panda-content'),shell=$('#agent-shell');
  if(shell&&content.contains(shell))$('#agent-panel').append(shell);
  const pages={workbench:home,market:marketPage,funds:fundsPage,library,allocation:allocationPage,holdings:holdingsPage,custom:customPage,watchlist:fundsPage,plans:plansPage,history:historyPage,account:accountPage,settings:settingsPage};
  content.innerHTML=state.conversationFocus&&conversationActive()?conversationPage():state.nav==='library'&&state.strategyCompareOpen?strategyComparePage():state.selected?strategyDetailWithAssistant(findStrategy(state.selected)):(pages[state.nav]||home)();
  document.body.classList.toggle('panda-market-page',state.nav==='market'&&!state.conversationFocus);
  if(state.nav==='holdings'){const sections=content.querySelectorAll('.panda-holdings-layout > section');if(sections[0])sections[0].id='holding-detail-section';if(sections[1])sections[1].id='holding-analysis-section'}
  const activeWorkspace=state.selected||['library','plans','history'].includes(state.nav)?'library':state.nav==='watchlist'?'funds':state.nav;
  document.querySelectorAll('.panda-sidebar [data-nav]').forEach(x=>x.classList.toggle('active',x.dataset.nav===activeWorkspace));
  $('#panda-data-status').textContent=state.holdings?'已连接同花顺账户':`已载入 ${state.catalog.length} 个策略`;
  ensureChrome();const ask=$('.suvi-ask-button');if(ask){ask.setAttribute('aria-expanded',String(state.agentDrawerOpen));ask.textContent=state.nav==='workbench'&&!state.selected?'✦ 与 SUVI 协作':state.agentDrawerOpen?'✦ 收起 SUVI':'✦ 问 SUVI'}
  placeAgent();renderSessions();const entry=$('#strategy-idle-chat-host')||$('.panda-workbench-chat-inner');if(entry&&conversationActive()&&!(state.nav==='library'&&!state.selected)&&!entry.querySelector('[data-chat-action="resume"]')){const top=entry.querySelector('.strategy-ask-top');(top||entry).insertAdjacentHTML(top?'beforeend':'afterbegin','<button class="suvi-resume-chat" type="button" data-chat-action="resume">'+(D.running?'查看正在进行的对话 →':'继续讨论 →')+'</button>')}
  if(state.pendingAnchor){const target=document.getElementById(state.pendingAnchor);if(target){state.pendingAnchor=null;requestAnimationFrame(()=>target.scrollIntoView({behavior:'smooth',block:'start'}))}}
  if(state.nav==='holdings'&&!state.holdings&&!state.holdingsError)loadHoldings();
  if(state.nav==='market'&&!state.marketIndices&&!state.marketIndicesError&&!state.marketIndicesLoading)loadMarketIndices();
}
function ensureChrome(){if(!$('#panda-toast'))document.body.insertAdjacentHTML('beforeend','<div id="panda-toast" class="panda-toast"></div>')}
function placeAgent(){const shell=$('#agent-shell'),panel=$('#agent-panel'),mainHost=$('#agent-main-host'),conversationHost=$('#agent-conversation-host'),composerHost=$('#agent-composer-host'),dashboardHost=$('#agent-workbench-chat-host'),strategyHost=$('#strategy-agent-host'),strategyIdleHost=$('#strategy-idle-chat-host');if(!shell||!panel)return;document.body.classList.toggle('suvi-preview-mode',!D.enabled);document.body.classList.remove('panda-agent-side','panda-conversation-active','panda-conversation-idle','panda-workbench-dashboard-idle','panda-workbench-dashboard-chat-active','suvi-drawer-open','panda-strategy-agent-embedded','panda-strategy-chat-idle','suvi-main-conversation');panel.hidden=true;if(mainHost){mainHost.append(shell);document.body.classList.add('suvi-main-conversation')}else if(strategyIdleHost&&(state.nav==='library'||state.selected)){strategyIdleHost.append(shell);document.body.classList.add('panda-strategy-agent-embedded','panda-strategy-chat-idle')}else if(strategyHost&&(state.nav==='library'||state.selected)){strategyHost.append(shell);document.body.classList.add('panda-strategy-agent-embedded')}else if(state.nav==='workbench'&&!state.selected&&dashboardHost){dashboardHost.append(shell);document.body.classList.add('panda-workbench-dashboard-idle')}else if(state.nav==='workbench'&&!state.selected&&(conversationHost||composerHost)){(conversationHost||composerHost).append(shell);document.body.classList.add(conversationHost?'panda-conversation-active':'panda-conversation-idle')}else{panel.append(shell);if(state.agentDrawerOpen){panel.hidden=false;document.body.classList.add('suvi-drawer-open')}}if($('#agent-input'))$('#agent-input').value=D.draft;renderAgentPanel()}

function textFromUserContent(content){return (content||[]).filter(x=>x.type==='text'&&!String(x.text||'').startsWith('[WORKBENCH_PAGE_CONTEXT]')).map(x=>x.text||'').join('\n')}
function reasoningText(item){for(const v of [item?.text,item?.summaryText,item?.summary]){if(typeof v==='string'&&v.trim())return v;if(Array.isArray(v)){const t=v.map(x=>typeof x==='string'?x:x?.text||'').filter(Boolean).join('\n');if(t)return t}}return ''}
function planText(plan){const rows=Array.isArray(plan)?plan:Array.isArray(plan?.steps)?plan.steps:[];return rows.map(x=>`${x.status==='completed'?'✓':x.status==='inProgress'||x.status==='in_progress'?'◌':'○'} ${x.step||x.text||x.description||''}`).join('\n')}
function friendlyAgentError(value){let message=String(value||'模型服务暂时无法响应。');try{const data=JSON.parse(message);message=data.error?.message||data.message||message}catch{}if(/not supported when using Codex with a ChatGPT account|model.*not supported|模型.*不可用/i.test(message))return '当前订阅不支持这个模型。请到「模型与推理设置」选择可用模型，然后重试。';return message}
function strategyCandidateArtifacts(text){const match=String(text||'').match(/\[\[STRATEGY_CANDIDATES:([\s\S]*?)\]\]/);if(!match)return {text:String(text||''),html:''};const ids=[...new Set(match[1].split(/[,，\s]+/).map(value=>value.trim()).filter(Boolean))].slice(0,3),items=ids.map(findStrategy).filter(Boolean);if(!items.length)return {text:String(text||'').replace(match[0],'').trim(),html:''};return {text:String(text||'').replace(match[0],'').trim(),html:`<section class="suvi-strategy-candidates"><strong>策略候选</strong>${items.map(item=>{const run=showcaseBest(item),metrics=run?.metrics||{},ok=run?.audit?.passed===true;return `<article><div><b>${esc(item.name)}</b><small>${esc(item.category)}${ok?` · 默认样本 ${esc(run.candidateName||run.fundCode||'—')} · ${esc(run.period?.start||'—')} 至 ${esc(run.period?.end||run.dataAsOf||'—')}`:''}</small>${ok?`<span>累计收益 ${pct(metrics.absoluteReturnPct??metrics.returnPct)} · 最大回撤 ${n(metrics.maxDrawdownPct)===null?'暂缺':num(metrics.maxDrawdownPct)+'%'} · 截至 ${esc(run.dataAsOf||'—')}</span>`:'<span>暂无通过校验的默认回测</span>'}</div><div><button type="button" data-action="open-strategy" data-id="${esc(item.id)}">查看规则与回测</button><button type="button" data-action="toggle-strategy-compare" data-id="${esc(item.id)}">加入对比</button></div></article>`}).join('')}<small>候选依据见上方回复。卡片数据来自目录默认样本，不代表按你的目标定制回测。</small></section>`}}
function renderAgentItem(m){
  if(m.type==='tool')return `<div class="agent-tool ${m.status==='failed'?'error':''}"><span>${['inProgress','running'].includes(m.status)?'<i class="spinner"></i>':'◇'}</span><div><strong>${esc(toolLabel(m.tool))}</strong><small>${m.status==='completed'?'已完成':m.status==='failed'?'未完成':'处理中'}</small></div></div>`;
  if(m.type==='reasoning')return `<div class="agent-reasoning"><small>分析摘要</small><div>${renderMarkdown(m.text)}</div></div>`;
  if(m.type==='plan')return `<div class="agent-plan"><strong>处理步骤</strong>${renderMarkdown(m.text)}</div>`;
  const index=D.messages.indexOf(m),actions=m.error?`<button type="button" data-chat-action="retry" data-index="${index}">重新编辑并发送</button><button type="button" data-nav="settings">模型设置</button>`:m.role==='assistant'?`<button type="button" data-chat-action="copy" data-index="${index}">复制回答</button>`:`<button type="button" data-chat-action="reuse" data-index="${index}">修改后重问</button>`;
  const candidates=m.role==='assistant'&&!m.error?strategyCandidateArtifacts(m.text):null,bodyText=(candidates?.text??m.text).replace(/\[\[MARKET_(?:PAGE|METRIC)_DRAFT:[\s\S]*?(?:\]\]|$)/g,'').trim();
  return `<article class="agent-message ${m.role} ${m.error?'error':''}"><small>${m.role==='user'?'你':m.error?'本轮未完成':'✦ SUVI'}</small><div>${m.error?`<p>${esc(friendlyAgentError(m.text))}</p>`:m.role==='assistant'?`${renderMarkdown(bodyText)}${candidates?.html||''}`:esc(m.text).replaceAll('\n','<br>')}</div><footer class="suvi-message-actions">${actions}</footer></article>`;
}
function renderAgentTimeline(){
  let html='',process=[];
  const flush=()=>{if(!process.length)return;const key=D.messages.indexOf(process[0]),busy=process.some(x=>x.streaming||['running','inProgress'].includes(x.status)),tools=process.filter(x=>x.type==='tool');html+=`<details class="suvi-process" data-process="${key}"><summary>${busy&&D.running?'正在处理':'查看处理过程'}${tools.length?` · ${tools.length} 项工具活动`:''}</summary>${process.map(renderAgentItem).join('')}</details>`;process=[]};
  for(const row of D.messages){if(row.type){process.push(row)}else{flush();html+=renderAgentItem(row)}}flush();return html;
}
function currentTurnItems(){const last=D.messages.map(x=>x.role).lastIndexOf('user');return D.messages.slice(last+1)}
function agentProgressMarkup(){
  const items=currentTurnItems(),lastTool=[...items].reverse().find(x=>x.type==='tool'&&['inProgress','running'].includes(x.status));
  const label=D.pendingInput?'需要你补充信息':D.sending&&!D.running?'正在建立对话':D.stopping?'正在停止':D.running?(lastTool?toolLabel(lastTool.tool):items.some(x=>x.role==='assistant'&&x.text)?'正在回复':'正在分析你的问题'):items.some(x=>x.error)?'本轮未完成':D.turnState==='interrupted'?'已停止，可继续追问':conversationActive()?'本轮已结束':'准备就绪';
  return `<div class="suvi-turn-status" role="status"><span class="${D.running?'working':''}">${D.running?'<i class="spinner"></i>':'◇'} ${esc(label)}</span>${D.running?`<small id="agent-elapsed">${Math.max(0,Math.floor((Date.now()-(D.turnStartedAt||Date.now()))/1000))} 秒</small>`:''}</div>`;
}
function toolLabel(name){return ({list_investment_strategies:'读取投资策略目录',run_investment_backtest:'运行真实策略回测',save_strategy_variant:'保存策略版本',get_account_brief:'读取账户简报',list_holdings:'读取真实持仓',analyze_portfolio:'分析持仓归因',list_orders:'查询真实订单',list_watchlist:'读取自选基金',set_watchlist:'更新自选基金',get_fund_accounts:'读取基金账户'})[name]||name||'基金工具'}
function sessionTime(value){const date=new Date(value),now=new Date();if(Number.isNaN(date.getTime()))return '';const clock=date.toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit',hour12:false});if(date.toDateString()===now.toDateString())return `今天 ${clock}`;const yesterday=new Date(now);yesterday.setDate(now.getDate()-1);if(date.toDateString()===yesterday.toDateString())return `昨天 ${clock}`;return date.toLocaleDateString('zh-CN',{month:'2-digit',day:'2-digit'})}
function renderSessions(){const host=$('#panda-sessions');if(!host)return;if(!D.enabled){host.innerHTML='<div class="panda-session-empty">桌面版可保存对话</div>';return}const all=D.sessions||[],query=D.sessionQuery.trim().toLocaleLowerCase(),matched=query?all.filter(s=>String(s.title||'').toLocaleLowerCase().includes(query)):all,pinned=matched.filter(s=>s.pinned),recent=matched.filter(s=>!s.pinned),visible=D.sessionsExpanded||query?recent:recent.slice(0,6),row=s=>`<div class="panda-session-row ${s.threadId===D.current?.threadId?'active':''}"><button class="panda-session-open" data-session="${esc(s.threadId)}" title="${esc(s.title||'新会话')}" ${D.running?'disabled':''}><strong>${esc(s.title||'新会话')}</strong><small>${esc(sessionTime(s.updatedAt))} · ${esc(s.mode==='api'?s.providerName||'API':'Codex')}</small></button><button class="panda-session-pin" data-session-pin="${esc(s.threadId)}" aria-label="${s.pinned?'取消置顶':'置顶'}" title="${s.pinned?'取消置顶':'置顶'}" ${D.running?'disabled':''}>${s.pinned?'★':'☆'}</button><button class="panda-session-delete" data-session-delete="${esc(s.threadId)}" aria-label="删除对话" title="删除对话" ${D.running?'disabled':''}>×</button></div>`;host.innerHTML=`<div class="panda-session-top"><span>最近对话</span><small>${all.length}</small></div>${all.length>6?`<label class="panda-session-search"><span>⌕</span><input id="session-search" type="search" value="${esc(D.sessionQuery)}" placeholder="搜索对话" aria-label="搜索对话"></label>`:''}<div class="panda-session-scroll">${pinned.length?`<div class="panda-session-group">置顶</div>${pinned.map(row).join('')}`:''}${visible.length?`<div class="panda-session-group">${pinned.length?'最近':'对话'}</div>${visible.map(row).join('')}`:!all.length?'<div class="panda-session-empty">从一个问题开始，记录会保存在这里。</div>':query?'<div class="panda-session-empty">没有找到相关对话</div>':''}</div>${!query&&recent.length>6?`<button class="panda-session-more" type="button" data-action="toggle-session-list">${D.sessionsExpanded?'收起对话':`查看全部 ${recent.length} 条对话`}</button>`:''}`}
