    D.messages.push({id:'local-'+Date.now(),role:'user',text});userAdded=true;D.running=true;D.turnState='running';D.stopping=false;D.followOutput=true;D.turnStartedAt=Date.now();D.draft='';state.conversationFocus=true;
    if($('#agent-input'))$('#agent-input').value='';render();$('#agent-input')?.focus();
