async function runBacktest(item,code,params,isDefault=false){state.busy=true;state.defaultLoading=isDefault?item.id:null;state.result=null;state.job={status:'running',stage:'queued',progress:1,logs:[{at:new Date().toISOString(),message:isDefault?'正在按策略卡相同参数准备默认回测。':'正在按当前参数准备回测。'}]};render();try{const created=await api('/api/strategy-invest/jobs',{strategyId:item.id,code:String(code||'').trim(),params});await pollJob(created.jobId)}catch(e){state.busy=false;state.defaultLoading=null;state.job={status:'failed',stage:'failed',progress:100,error:e.message,logs:[{at:new Date().toISOString(),message:e.message}]};render()}}
