function openStrategyPlanDraft(){if(state.result?.status!=='ok'||state.result.audit?.passed!==true){toast('请先完成并核对回测，再制定计划。');return}const item=findStrategy(state.selected),run=state.result,dialog=$('#panda-dialog'),host=$('#panda-dialog-content'),fund=run.candidateName||run.fundCode||'策略池',amount=run.parameters?.amount??run.parameters?.initial_capital;host.innerHTML=`<div class="panda-dialog-head"><div><small>制定计划</small><h2>${esc(currentVariant(item.id)?.name||item.name)}</h2><p>${esc(fund)} · 回测数据截至 ${esc(run.dataAsOf||'—')}</p></div><button type="button" data-action="close-dialog" aria-label="关闭">×</button></div><form id="strategy-plan-draft-form" class="strategy-plan-draft-form"><div class="strategy-plan-draft-backtest"><span>本次计划依据</span><strong>${esc(fund)} · ${esc(run.period?.start||'—')} 至 ${esc(run.period?.end||run.dataAsOf||'—')}</strong><small>沿用当前基金和策略参数${n(amount)!==null?`，单次或初始投入 ${money(amount)}`:''}。如要更换基金、投入金额或规则，先调整参数并重新回测。</small></div><label>方案名称<input name="name" maxlength="80" value="${esc((currentVariant(item.id)?.name||item.name)+' · '+(run.fundCode||'策略池'))}" required></label><label>投资目标（选填）<input name="investmentGoal" maxlength="160" placeholder="例如：三年后用于教育支出"></label><label>资金预计使用时间（选填）<input name="capitalUseHorizon" maxlength="48" placeholder="例如：三年内不用"></label><p>保存后成为本机计划草稿，不会自动跟踪或交易。</p><div class="panda-dialog-actions"><button type="button" class="panda-button quiet" data-action="plan-edit-before-save">先调整参数</button><button type="submit" class="panda-button primary">保存计划草稿</button></div></form>`;dialog.showModal()}
async function savePlan(metadata={}){if(state.result?.status!=='ok'||state.result.audit?.passed!==true)return;const item=findStrategy(state.selected),target=state.result.fundCode||'行业基金池',created=await api('/api/strategy-plans',{strategyId:item.id,code:state.result.fundCode,fundPool:state.result.fundPool,amount:state.result.parameters?.amount??state.result.parameters?.initial_capital,params:state.result.parameters,name:metadata.name||`${currentVariant(item.id)?.name||item.name} · ${target}`,investmentGoal:metadata.investmentGoal||'',capitalUseHorizon:metadata.capitalUseHorizon||'',runId:state.result.runId,dataAsOf:state.result.dataAsOf});state.plans=await api('/api/strategy-plans');const host=$('#panda-dialog-content');if(host)host.innerHTML=`<div class="panda-dialog-head"><div><small>方案已保存</small><h2>${esc(created.name)}</h2><p>保存在本机「我的页面」的策略计划中；当前状态：草稿。</p></div><button type="button" data-action="close-dialog" aria-label="关闭">×</button></div><div class="strategy-plan-saved"><p>已保存回测版本、标的、参数与资金安排。开启追踪需单独确认；保存不会自动买入。</p><div class="panda-dialog-actions"><button type="button" class="panda-button quiet" data-action="close-dialog">留在策略详情</button><button type="button" class="panda-button primary" data-action="open-saved-plan">查看我的计划</button></div></div>`;if(!$('#panda-dialog')?.open)$('#panda-dialog')?.showModal()}
