document.addEventListener('click',async e=>{const t=e.target.closest('[data-action],[data-nav],[data-prompt],[data-session],[data-session-pin],[data-session-delete]');if(!t)return;try{if(t.dataset.prompt){if(state.nav!=='workbench'||state.selected){state.nav='workbench';state.selected=null;state.agentDrawerOpen=false;render()}const input=$('#agent-input');if(input){D.draft=t.dataset.prompt;input.value=D.draft;updateComposerState();input.focus()}if(!D.enabled){state.previewPrompt=t.dataset.prompt;render()}return}if(t.dataset.nav){state.nav=t.dataset.nav;state.selected=null;state.result=null;state.agentDrawerOpen=false;render();if(state.nav==='plans')refreshPlanPerformance();return}if(t.dataset.session){await resumeSession(t.dataset.session);state.nav='workbench';state.selected=null;render();return}if(t.dataset.sessionPin){const row=D.sessions.find(x=>x.threadId===t.dataset.sessionPin);D.sessions=await desktopCall(window.fundDesktop.updateSession({threadId:row.threadId,pinned:!row.pinned}));D.current=D.sessions.find(x=>x.threadId===D.current?.threadId)||D.current;renderSessions();return}if(t.dataset.sessionDelete){await deleteSession(t.dataset.sessionDelete);return}const a=t.dataset.action;if(a==='toggle-session-list'){D.sessionsExpanded=!D.sessionsExpanded;renderSessions();return}if(a==='login-codex'){const result=await desktopCall(window.fundDesktop.startSubscriptionLogin());toast(result.started?'已打开 Codex / ChatGPT 登录页；完成登录后点击“刷新模型与登录状态”。':'无法启动订阅登录。');return}if(a==='refresh-model-status'){D.status=await desktopCall(window.fundDesktop.getStatus());render();toast('Codex 模型与登录状态已刷新。');return}if(a==='test-api-provider'){toast('正在检查 API 服务和基金工具连接…');const result=await desktopCall(window.fundDesktop.testProvider());toast(result.completed&&result.toolCall&&result.toolResult?'API 连通，基金工具调用成功。':'API 可连接，但基金工具调用未完整通过。');return}if(a==='toggle-context'){state.contextCollapsed=!state.contextCollapsed;render();return}if(a==='toggle-agent'){if(state.nav==='workbench'&&!state.selected){$('#agent-input')?.focus()}else{state.agentDrawerOpen=!state.agentDrawerOpen;render()}return}if(a==='close-agent'){state.agentDrawerOpen=false;render();return}if(a==='new-task'){if(D.enabled)await newSession();else{state.previewPrompt=null;render()}return}if(a==='open-strategy')await openStrategy(t.dataset.id);else if(a==='open-run')await openRun(t.dataset.id);else if(a==='back-library'){state.selected=null;state.variant=null;state.result=null;state.nav='library';render()}else if(a==='edit-params'){state.paramEditing=true;state.paramsExpanded=true;render();requestAnimationFrame(()=>document.querySelector('.panda-controls-column')?.scrollIntoView({block:'start',behavior:'smooth'}))}else if(a==='cancel-param-edit'){state.paramEditing=false;render()}else if(a==='toggle-params'){state.paramsExpanded=!state.paramsExpanded;render()}else if(a==='load-variant'){state.variant=state.variants.find(x=>x.id===t.dataset.id);state.result=null;state.job=null;state.paramEditing=true;state.paramsExpanded=true;render()}else if(a==='save-plan')openStrategyPlanDraft();else if(a==='open-saved-plan'){if($('#panda-dialog')?.open)$('#panda-dialog').close();state.nav='plans';state.selected=null;render();refreshPlanPerformance()}else if(a==='plan-action')await planAction(t.dataset.id,t.dataset.planAction);else if(a==='refresh-holdings'){state.holdings=null;state.analysis=null;render();loadHoldings()}else if(a==='drill-fund')await drillFund(t.dataset.code);else if(a==='close-dialog')$('#panda-dialog').close();else if(a==='remove-watch'){const b=await api('/api/watchlist',{code:t.dataset.code,remove:true});state.watchlist=b.watchlist||[];render()}else if(a==='pick-for-strategy'){state.pendingCode=t.dataset.code;state.nav='library';state.selected=null;$('#panda-dialog')?.close();render();toast(`已选择基金 ${t.dataset.code}，打开策略即可回测。`)}else if(a==='login-fund')await loginFund(false);else if(a==='switch-account')showAccountLoginDialog(true,true);else if(a==='confirm-switch-account')await loginFund(true)}catch(err){toast(err.message)}});
document.addEventListener('submit',async e=>{e.preventDefault();try{if(e.target.id==='strategy-plan-draft-form'){const form=e.target,button=form.querySelector('[type="submit"]'),raw=Object.fromEntries(new FormData(form));if(button){button.disabled=true;button.textContent='正在保存…'}try{await savePlan(raw)}catch(error){if(button){button.disabled=false;button.textContent='保存方案'}throw error}}else if(e.target.id==='panda-strategy-form'){const item=findStrategy(state.selected),intent=e.submitter?.value||'run';if(intent==='save')await saveVariant(e.target,item);else await startBacktest(e.target,item)}else if(e.target.id==='watch-form'){const raw=Object.fromEntries(new FormData(e.target)),b=await api('/api/watchlist',{code:raw.code,name:raw.name});state.watchlist=b.watchlist||[];render()}else if(e.target.id==='model-form'){const raw=Object.fromEntries(new FormData(e.target));D.settings=await desktopCall(window.fundDesktop.saveProvider({mode:'subscription',model:raw.model,effort:raw.effort}));D.status=await desktopCall(window.fundDesktop.getStatus());toast('Codex 订阅已设为新会话默认模型');render()}else if(e.target.getAttribute('id')==='api-provider-form'){
  const form=e.target,saveButton=form.querySelector('[data-api-save]'),status=form.querySelector('[data-api-save-status]');
  if(saveButton){saveButton.disabled=true;saveButton.textContent='正在保存并启用…'}
  if(status){status.className='api-save-feedback pending';status.textContent='正在安全保存密钥并连接模型服务…'}
  try{
    const raw=Object.fromEntries(new FormData(form));
    D.settings=await desktopCall(window.fundDesktop.saveProvider({mode:'api',id:raw.providerId||undefined,name:raw.name,model:raw.model,baseUrl:raw.baseUrl,apiKey:raw.apiKey,effort:raw.effort,authHeaderName:raw.authHeaderName}));
    D.status=await desktopCall(window.fundDesktop.getStatus());
    toast('API 服务已保存并启用');render();
  }catch(err){
    if(status){status.className='api-save-feedback error';status.textContent=`保存失败：${err.message||'请检查 API Key 后重试。'}`}
    throw err;
  }finally{
    if(saveButton?.isConnected){saveButton.disabled=false;saveButton.textContent='保存并使用此 API'}
  }
}else if(e.target.id==='agent-form'){await sendAgent($('#agent-input').value.trim())}else if(e.target.id==='agent-question-form'){const request=D.pendingInput,form=new FormData(e.target),answers={};for(const [i,q] of (request.questions||[]).entries()){const value=String(form.get(`custom-answer-${i}`)||'').trim()||String(form.get(`answer-${i}`)||'').trim();if(!value)throw new Error('请选择或填写回答，也可以填写暂不确定。');answers[q.id]={answers:[value]}}await desktopCall(window.fundDesktop.answerUserInput({requestId:request.requestId,answers}));D.pendingInput=null;renderAgentPanel()}}catch(err){toast(err.message)}});
document.addEventListener('change',e=>{
  const form=e.target?.form;
  if(form?.getAttribute('id')==='api-provider-form'&&e.target.name==='provider-preset'){
    const value=e.target.value,preset=API_PRESETS.find(x=>x.id===value),saved=preset?savedProviderForPreset(preset):(D.settings?.providers||[]).find(x=>`saved:${x.id}`===value);
    form.elements.providerId.value=saved?.id||'';
    form.elements.name.value=preset?.name||saved?.name||'';
    form.elements.model.value=preset?.model||saved?.model||'';
    form.elements.baseUrl.value=preset?.baseUrl||saved?.baseUrl||'';
    form.elements.authHeaderName.value=preset?.authHeaderName||saved?.authHeaderName||'';
    form.elements.effort.value=saved?.effort||'high';
    form.elements.apiKey.value='';
    form.elements.apiKey.required=!saved?.keyConfigured;
    form.elements.apiKey.placeholder=saved?.keyConfigured?'该服务商已有密钥；留空可继续使用':'粘贴服务商提供的 API Key';
    return;
  }
  if(e.target?.name!=='model'||form?.id!=='model-form')return;
  const model=modelRows().find(x=>x.id===e.target.value),efforts=(model?.supportedReasoningEfforts||[]).map(x=>typeof x==='string'?x:x?.reasoningEffort).filter(Boolean),select=form.elements.effort,current=select.value;
  select.innerHTML=(efforts.length?efforts:['low','medium','high','xhigh']).map(x=>`<option value="${esc(x)}" ${x===current?'selected':''}>${esc(({none:'关闭',low:'低',medium:'中',high:'高',xhigh:'很高',max:'最高',ultra:'超高'})[x]||x)}</option>`).join('');
  if(!efforts.includes(current)&&efforts.length)select.value=efforts[0];
});
$('#agent-new').addEventListener('click',()=>D.enabled?newSession().catch(e=>toast(e.message)):(state.previewPrompt=null,render()));
$('#agent-stop').addEventListener('click',async()=>{if(!D.running||D.stopping)return;D.stopping=true;renderAgentPanel();try{await desktopCall(window.fundDesktop.interrupt())}catch(e){D.stopping=false;renderAgentPanel();toast(e.message)}});
$('#agent-rename').addEventListener('click',async()=>{if(!D.current)return;const title=prompt('会话名称',D.current.title||'');if(!title?.trim())return;D.sessions=await desktopCall(window.fundDesktop.updateSession({threadId:D.current.threadId,title:title.trim()}));D.current=D.sessions.find(x=>x.threadId===D.current.threadId)||D.current;renderSessions();renderAgentPanel()});
$('#agent-pin').addEventListener('click',async()=>{if(!D.current)return;D.sessions=await desktopCall(window.fundDesktop.updateSession({threadId:D.current.threadId,pinned:!D.current.pinned}));D.current=D.sessions.find(x=>x.threadId===D.current.threadId);renderSessions();renderAgentPanel()});
$('#agent-archive').addEventListener('click',async()=>{if(!D.current)return;D.sessions=await desktopCall(window.fundDesktop.archiveSession(D.current.threadId));D.current=null;D.messages=[];render()});
async function deleteSession(threadId){const row=D.sessions.find(x=>x.threadId===threadId);if(!row)return;if(D.running){toast('请先停止或等待当前 Agent 任务完成。');return}if(!confirm(`删除对话“${row.title}”？删除后将从历史会话中移除。`))return;const wasCurrent=D.current?.threadId===threadId,outcome=await desktopCall(window.fundDesktop.deleteSession(threadId));D.sessions=Array.isArray(outcome)?outcome:(outcome?.sessions||[]);if(wasCurrent){D.current=null;D.messages=[];D.tools.clear();D.pendingInput=null;D.turnStartedAt=null}render();if(wasCurrent&&D.sessions.length){try{await resumeSession(D.sessions[0].threadId)}catch(e){toast(`会话已删除；下一条会话加载失败：${e.message}`);return}}toast(outcome?.warning?'对话已从本机历史移除；模型服务归档暂未完成。':'对话已删除')}
$('#agent-delete').addEventListener('click',()=>D.current&&deleteSession(D.current.threadId).catch(e=>toast(e.message)));
$('#agent-input').addEventListener('input',e=>{D.draft=e.currentTarget.value;updateComposerState()});
$('#agent-input').addEventListener('keydown',e=>{if(e.key==='Enter'&&(e.ctrlKey||e.metaKey)&&!e.isComposing){e.preventDefault();if(String(e.currentTarget.value||'').trim()&&!D.running)$('#agent-form').requestSubmit()}});
document.addEventListener('input',e=>{if(e.target?.id!=='session-search')return;const start=e.target.selectionStart;D.sessionQuery=e.target.value;renderSessions();const input=$('#session-search');if(input){input.focus();input.setSelectionRange(start,start)}});
document.addEventListener('click',e=>{const item=e.target.closest('[data-nav="holdings"][data-anchor]');if(item){state.holdingAnchor=item.dataset.anchor;state.pendingAnchor=item.dataset.anchor}},true);
async function ensureStrategySession(){if(!D.enabled)return;const stored=state.strategySessionThreadId;if(stored&&D.current?.threadId===stored)return;if(stored&&D.sessions.some(session=>session.threadId===stored))await resumeSession(stored);if(stored&&D.current?.threadId===stored)return;if(!(D.current&&!D.messages.length&&!D.running))await newSession({stayOnPage:true,strategy:true});if(D.current){state.strategySessionThreadId=D.current.threadId;try{localStorage.setItem('suvi-strategy-thread',state.strategySessionThreadId)}catch{}}}
async function beginStrategyConversation(prompt){if(!prompt||D.running)return;state.strategyExploreStage='discuss';state.strategyFirstAnswer=String(prompt).trim();if(!D.enabled){state.previewPrompt=prompt;state.conversationFocus=true;render();return}try{await ensureStrategySession();await sendAgent(prompt)}catch(error){toast(error.message||'无法创建策略讨论，请重试。')}}
document.addEventListener('click',async e=>{const target=e.target.closest('[data-strategy-goal],[data-strategy-example],[data-action="strategy-next-example"],[data-action="resume-strategy"]');if(!target)return;e.preventDefault();e.stopImmediatePropagation();if(target.dataset.action==='strategy-next-example'){state.strategyExampleIndex=(state.strategyExampleIndex+1)%STRATEGY_EXAMPLES.length;const example=document.querySelector('[data-strategy-example]');if(example){example.dataset.strategyExample=STRATEGY_EXAMPLES[state.strategyExampleIndex];example.textContent=STRATEGY_EXAMPLES[state.strategyExampleIndex]+' ↗'}return}if(target.hasAttribute('data-strategy-goal')||target.hasAttribute('data-strategy-example')){const prompt=String(target.dataset.strategyGoal||target.dataset.strategyExample||'');state.strategyGoalFresh=Boolean(state.strategySessionThreadId&&D.sessions.some(session=>session.threadId===state.strategySessionThreadId));D.draft=prompt;document.querySelectorAll('[data-strategy-goal]').forEach(button=>button.classList.toggle('is-selected',button===target));const input=$('#agent-input');if(input){input.value=prompt;updateComposerState();input.focus();input.setSelectionRange(prompt.length,prompt.length);input.scrollIntoView({block:'nearest',behavior:'smooth'})}return}const id=state.strategySessionThreadId;if(!id)return;state.strategyGoalFresh=false;await resumeSession(id);state.nav='library';state.conversationFocus=true;state.strategyExploreStage='discuss';render()},true);
document.addEventListener('click',async e=>{const target=e.target.closest('[data-action="explain-strategy"]');if(!target)return;e.stopPropagation();e.stopImmediatePropagation();const item=findStrategy(target.dataset.id);if(!item)return;const backtest=target.dataset.view==='backtest';await openStrategy(item.id);const prompt=backtest?`请解读「${item.name}」当前默认参数的历史回测。先核对实际标的、回测区间、数据截至日期与基准，再解释累计收益、超额收益和最大回撤各代表什么；若数据缺失请直说，不要补造结果。`:`请用普通投资者能理解的话讲清「${item.name}」的执行逻辑：何时投入、何时调整、需要多久操作一次，以及哪些情形不适合使用。请引用当前策略 Skill 的具体规则，不要只讲概念。`;await beginStrategyConversation(prompt);if(backtest)requestAnimationFrame(()=>document.querySelector('.panda-backtest-column')?.scrollIntoView({block:'start',behavior:'smooth'}))},true);
document.addEventListener('click',async e=>{const target=e.target.closest('[data-strategy-start],[data-strategy-prompt]');if(!target)return;const prompt=target.dataset.strategyStart||target.dataset.strategyPrompt;await beginStrategyConversation(prompt)});
document.addEventListener('click',e=>{const target=e.target.closest('[data-strategy-suggest]');if(!target)return;beginStrategyConversation(target.dataset.strategySuggest)});
document.addEventListener('click',e=>{const category=e.target.closest('[data-strategy-category]');if(category){state.strategyCategory=category.dataset.strategyCategory;state.strategyShowAll=false;render();return}const showAll=e.target.closest('[data-action="toggle-strategy-all"]');if(showAll){state.strategyShowAll=!state.strategyShowAll;render()}});
document.addEventListener('input',e=>{if(e.target?.id!=='strategy-search')return;const input=e.target,start=input.selectionStart;state.strategySearch=input.value;state.strategyShowAll=false;render();const next=$('#strategy-search');if(next){next.focus();next.setSelectionRange(start,start)}});
document.addEventListener('click',async e=>{const target=e.target.closest('[data-action="open-strategy"],[data-action="open-strategy-params"],[data-action="start-strategy-plan"]');if(!target)return;e.preventDefault();e.stopImmediatePropagation();const item=findStrategy(target.dataset.id);if(!item){toast('策略已不可用，请刷新目录。');return}const content=$('#panda-content'),position={top:content?.scrollTop||window.scrollY||0,left:content?.scrollLeft||0};if(state.strategyCompareOpen){state.strategyCompareScroll=position;state.strategyDetailReturnCompare=true;state.strategyCompareOpen=false}else state.strategyReturnScroll=position;state.conversationFocus=false;await openStrategy(item.id);if(target.dataset.action==='open-strategy-params'){state.paramEditing=true;state.paramsExpanded=true;render();requestAnimationFrame(()=>document.querySelector('.panda-controls-column')?.scrollIntoView({block:'start',behavior:'smooth'}))}if(target.dataset.action==='start-strategy-plan'){if(state.result?.status==='ok'&&state.result.audit?.passed===true)openStrategyPlanDraft();else toast('默认样本回测尚未通过校验。请在详情中选择基金并完成回测。')}},true);
document.addEventListener('click',e=>{if(!e.target.closest('[data-action="plan-edit-before-save"]'))return;e.preventDefault();e.stopImmediatePropagation();$('#panda-dialog')?.close();state.paramEditing=true;state.paramsExpanded=true;render();requestAnimationFrame(()=>document.querySelector('.panda-controls-column')?.scrollIntoView({block:'start',behavior:'smooth'}))},true);
document.addEventListener('click',e=>{const action=e.target.closest('[data-action="toggle-strategy-favorite"],[data-action="toggle-strategy-favorites"],[data-action="clear-strategy-search"],[data-action="retry-showcase"]');if(!action)return;e.preventDefault();e.stopPropagation();if(action.dataset.action==='toggle-strategy-favorite'){const id=action.dataset.id;state.strategyFavorites=state.strategyFavorites.includes(id)?state.strategyFavorites.filter(value=>value!==id):[...state.strategyFavorites,id];try{localStorage.setItem('suvi-strategy-favorites',JSON.stringify(state.strategyFavorites))}catch{} }else if(action.dataset.action==='toggle-strategy-favorites')state.strategyFavoritesOnly=!state.strategyFavoritesOnly;else if(action.dataset.action==='clear-strategy-search')state.strategySearch='';else{const item=findStrategy(action.dataset.id);if(item){delete state.showcases[item.id];loadShowcase(item,true).catch(error=>{state.showcases[item.id]={status:'blocked',missingData:[error.message]};render()})}}render()});

document.addEventListener('change',e=>{const key=e.target?.dataset?.strategyPref;if(!key)return;state.strategyPrefs[key]=e.target.value;render()});
document.addEventListener('click',e=>{const target=e.target.closest('[data-action="toggle-strategy-compare"]');if(!target)return;e.stopPropagation();const id=target.dataset.id;if(state.strategyCompare.includes(id))state.strategyCompare=state.strategyCompare.filter(value=>value!==id);else if(state.strategyCompare.length<3)state.strategyCompare.push(id);else{toast('最多对比 3 个策略');return}if(state.strategyCompare.length<2)state.strategyCompareOpen=false;render()},true);
document.addEventListener('click',e=>{const target=e.target.closest('[data-action="ask-strategy-comparison"]');if(!target)return;e.preventDefault();const items=state.strategyCompare.map(findStrategy).filter(Boolean);if(items.length<2){toast('至少选择 2 项策略');return}const names=items.map(item=>item.name).join('、');beginStrategyConversation(`请比较${names}。结合我已经说明的目标和偏好，先比较运行规则、投入方式、操作频率和主要风险；再核对各自回测标的、区间、收益及回撤口径。口径不同的结果不要直接排高低，请指出哪一项更符合我的条件及不匹配处。`)},true);
document.addEventListener('click',e=>{if(e.target.closest('[data-action="back-library"]')){e.preventDefault();e.stopImmediatePropagation();if(state.strategyDetailReturnCompare){state.strategyDetailReturnCompare=false;state.selected=null;state.variant=null;state.result=null;state.strategyCompareOpen=true;render();requestAnimationFrame(()=>{const content=$('#panda-content');if(content)content.scrollTop=state.strategyCompareScroll.top;window.scrollTo(0,state.strategyCompareScroll.top)});return}const content=$('#panda-content'),fromCompare=state.strategyCompareOpen;state.strategyCompareOpen=false;state.selected=state.strategyCompareReturnSelected||null;state.strategyCompareReturnSelected=null;state.nav='library';if(!state.selected){state.variant=null;state.result=null}render();const position=fromCompare?state.strategyCompareOriginScroll:state.strategyReturnScroll;requestAnimationFrame(()=>{const next=$('#panda-content');if(next)next.scrollTop=position?.top||0;window.scrollTo(0,position?.top||0)});return}if(e.target.closest('[data-action="open-strategy-compare"]')){e.stopPropagation();if(state.strategyCompare.length<2){toast('至少选择 2 项策略');return}const content=$('#panda-content');state.strategyCompareOriginScroll={top:content?.scrollTop||window.scrollY||0,left:content?.scrollLeft||0};state.strategyCompareReturnSelected=state.selected||null;state.strategyCompareOpen=true;render()}},true);
document.addEventListener('click',e=>{const target=e.target.closest('[data-market-action],[data-market-tab],[data-market-prompt]');if(!target)return;if(target.dataset.marketPrompt){state.agentDrawerOpen=true;if(!D.enabled)state.previewPrompt=target.dataset.marketPrompt;render();const input=$('#agent-input');if(input&&D.enabled){D.draft=target.dataset.marketPrompt;input.value=D.draft;updateComposerState();input.focus()}return}if(target.dataset.marketTab){state.marketTab=target.dataset.marketTab;state.marketSelectedFund=null;render();return}if(target.dataset.marketAction==='refresh-indexes'){state.marketIndicesError='';loadMarketIndices(true);return}if(target.dataset.marketAction==='fund-detail'){state.marketSelectedFund=target.dataset.id;state.marketTab='holdings';render();return}if(target.dataset.marketAction==='back-mine'){state.marketSelectedFund=null;state.marketTab='holdings';render()}},true);

document.addEventListener('click',e=>{const target=e.target.closest('[data-action="return-context"],[data-action="toggle-agent"],[data-nav],[data-session]');if(!target)return;if(target.dataset.action==='return-context'){e.stopImmediatePropagation();state.conversationFocus=false;render();return}if(target.dataset.action==='toggle-agent'&&conversationActive()){e.stopImmediatePropagation();state.conversationFocus=true;render();$('#agent-input')?.focus();return}if(target.dataset.nav)state.conversationFocus=false;else if(target.dataset.session)state.conversationFocus=true},true);

document.addEventListener('change',e=>{if(e.target.id!=='custom-page-title')return;customPageConfig.title=e.target.value.trim().slice(0,32)||'我的投资页面';saveCustomPage();render()});
document.addEventListener('click',async e=>{const target=e.target.closest('[data-custom-action]');if(!target)return;const action=target.dataset.customAction,id=target.dataset.id,blocks=customPageConfig.blocks;if(action==='edit'||action==='done'){customEditing=action==='edit';render();if(action==='done')toast('页面已保存到此设备');return}if(action==='toggle'){customPageConfig.blocks=blocks.includes(id)?blocks.filter(x=>x!==id):[...blocks,id];saveCustomPage();render();return}if(action==='up'||action==='down'){const from=blocks.indexOf(id),to=from+(action==='up'?-1:1);if(to<0||to>=blocks.length)return;[blocks[from],blocks[to]]=[blocks[to],blocks[from]];saveCustomPage();render();return}if(action==='preview'){customPreview=target.dataset.size;render();return}if(action==='share'){const template={schemaVersion:1,title:customPageConfig.title,blocks:[...blocks]},json=JSON.stringify(template,null,2);$('#panda-dialog-content').innerHTML=`<div class="panda-dialog-head"><div><small>页面模板 · 分享预览</small><h2>${esc(template.title)}</h2><p>包含 ${blocks.map(x=>esc(CUSTOM_BLOCKS[x])).join('、')||'零个'}模块。模板不含账户、持仓、计划或聊天内容。</p></div><button data-action="close-dialog">×</button></div><div class="suvi-share-preview"><strong>页面模板</strong><p>社区发布接口尚未接入。现在可以复制模板配置，用于评审或后续发布流程。</p><pre>${esc(json)}</pre><button type="button" data-custom-action="copy-template">复制模板配置</button></div>`;$('#panda-dialog').showModal();return}if(action==='copy-template'){try{await navigator.clipboard.writeText(JSON.stringify({schemaVersion:1,title:customPageConfig.title,blocks:[...blocks]},null,2));toast('已复制页面模板配置')}catch{toast('复制失败，请手动选择模板内容')}}});


$('#agent-messages').addEventListener('scroll',()=>{const host=$('#agent-messages');if(!host.clientHeight)return;D.followOutput=host.scrollHeight-host.clientHeight-host.scrollTop<72;const jump=$('#agent-jump-latest');if(jump)jump.hidden=D.followOutput});
document.addEventListener('click',async e=>{const t=e.target.closest('[data-chat-action]');if(!t)return;const action=t.dataset.chatAction;if(action==='resume'){state.conversationFocus=true;render();$('#agent-input')?.focus();return}if(action==='latest'){D.followOutput=true;const host=$('#agent-messages');host.scrollTop=host.scrollHeight;t.hidden=true;return}const row=D.messages[Number(t.dataset.index)];if(action==='copy'){try{await navigator.clipboard.writeText(row?.text||'');toast('回答已复制')}catch{toast('复制失败，请选择文字复制')}return}const text=action==='retry'?D.messages.slice(0,Number(t.dataset.index)).reverse().find(x=>x.role==='user')?.text:row?.text;if(text){D.draft=text;$('#agent-input').value=text;updateComposerState();$('#agent-input').focus()}});

async function bootstrap(){ensureChrome();setInterval(()=>{if(D.running&&$('#agent-elapsed'))$('#agent-elapsed').textContent=Math.max(0,Math.floor((Date.now()-(D.turnStartedAt||Date.now()))/1000))+' 秒'},1000);setInterval(()=>{if(state.nav==='market'&&!document.hidden&&!state.marketIndicesLoading)loadMarketIndices()},60000);try{await refreshLocal();render();startMonitor();loadHoldings();loadShowcases();if(D.enabled)await initDesktop();else render()}catch(e){$('#panda-content').innerHTML=`<div class="panda-empty-page"><div><div class="empty-symbol">!</div><h2>本地服务尚未启动</h2><p>${esc(e.message)}</p></div></div>`}}
bootstrap();
